import calendar
from datetime import date

_MIN_YEAR = 1
_MAX_YEAR = 9999


def _check_months(months):
    if isinstance(months, bool) or not isinstance(months, int):
        raise TypeError("months must be an int")


def add_months(day, months):
    """The date `months` months after `day`, clamped to the end of the month. See TASK.md."""
    _check_months(months)
    total = day.year * 12 + (day.month - 1) + months
    year, month_index = divmod(total, 12)
    if year < _MIN_YEAR or year > _MAX_YEAR:
        raise ValueError("resulting date is outside the years 1 to 9999")
    month = month_index + 1
    last_day = calendar.monthrange(year, month)[1]
    return date(year, month, min(day.day, last_day))


def _add_months_or_none(day, months):
    """Like add_months, but returns None when the result is out of range."""
    try:
        return add_months(day, months)
    except ValueError:
        return None


def months_between(start, end):
    """Whole months from `start` to `end`. See TASK.md."""
    if start > end:
        return -months_between(end, start)
    # add_months(start, n) is strictly increasing in n, so search for the
    # largest n with add_months(start, n) <= end. Start from the month
    # difference, which is at most one above the answer, then adjust.
    n = (end.year - start.year) * 12 + (end.month - start.month)
    while n > 0:
        candidate = _add_months_or_none(start, n)
        if candidate is not None and candidate <= end:
            break
        n -= 1
    while True:
        candidate = _add_months_or_none(start, n + 1)
        if candidate is None or candidate > end:
            break
        n += 1
    return n
